$('detailDownload').onclick=async()=>{try{if(!results.length)return;const imgs=await Promise.all(results.map(x=>image(x.url)));let width=Math.min(1008,...imgs.map(x=>x.width));const totalHeight=()=>imgs.reduce((sum,x)=>sum+Math.round(width*x.height/x.width),0);if(totalHeight()>30000)width=Math.max(1,Math.floor(width*29975/totalHeight()));const height=totalHeight();if(height>30000)throw Error('长图过长，请使用切片下载');const c=document.createElement('canvas');c.width=width;c.height=height;let top=0;for(const img of imgs){const h=Math.round(width*img.height/img.width);c.getContext('2d').drawImage(img,0,top,width,h);top+=h;}const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('长图导出失败，请下载切片');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='商品详情页长图.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(e){status(e.message);}};
async function downloadGroup(items,fileName="织景本组图片.zip",options={}){try{const {downloadImageArchive}=await import('/image-download.js?v=20261011-latest-versions1');await downloadImageArchive(items,fileName,{detail:items.some(item=>item.detailPage),...(options.grouped===false?{nameFor:item=>'图片_'+item.number}:{}),...options});}catch(error){toast(error.message);}}

function latestSlices(items){return splitDetailVersions(items).current;}
function rememberDetailVersions(items){const byNumber=new Map(detailArchive.map(x=>[x.number,x]));for(const item of items)byNumber.set(item.number,item);detailArchive=[...byNumber.values()];}
function replacedSlices(){const active=new Set(results.map(x=>x.number));return detailItems().filter(x=>!active.has(x.number));}
function detailItems(){const group=viewingHistory?historyGroupKey:currentGroupKey;const byNumber=new Map(detailArchive.filter(x=>!x.deletedAt&&detailGroupKey(x)===group).map(x=>[x.number,x]));for(const item of results)byNumber.set(item.number,item);return [...byNumber.values()].sort((a,b)=>(a.detailSliceIndex??0)-(b.detailSliceIndex??0)||b.number-a.number);}
const resultMarker=document.createComment('current-detail-results');$('detailResult').before(resultMarker);let historySnapshot=null;
const editorStateIds=['detailEditPrompt','detailEditScope','detailEditStatus','detailEditProgress','detailGenerationTask','detailReferenceUpload','detailReferenceRemove','detailReferencePreview'];
function captureEditor(){return editorStateIds.map(id=>{const el=$(id);return {id,value:el.value,hidden:el.hidden,text:el.children.length?null:el.textContent,html:id==='detailEditProgress'?el.innerHTML:null,className:el.className,style:el.style.cssText};});}
function openGroup(items,host){if(busy||referenceLoading)return toast('请等待详情任务完成');if(!host)return window.openGenerationHistory?.('detail',false);if(!historySnapshot){historySnapshot={editor:captureEditor(),batch,selected:new Set(selected),referenceImage,referenceName:$('detailReferencePreview').querySelector('span').textContent,previewTop:$('detailPreviewViewport').scrollTop};}host.append($('detailResult'));viewingHistory=true;$('detailGenerationTask').hidden=true;historyGroupKey=items[0]?.detailGroupId||items[0]?.batchId||items[0]?.jobId;rememberDetailVersions(items);results=latestSlices(items);setBatch(false);$('detailEditPrompt').value='';$('detailEditStatus').textContent='';$('detailEditProgress').hidden=true;$('detailReferenceRemove').onclick();$('detailEditScope').value=String(results[0]?.number||'all');renderSlices();$('detailPreviewViewport').scrollTop=0;}
function updateHistory(items){if(!viewingHistory)return;detailArchive=detailArchive.filter(x=>detailGroupKey(x)!==historyGroupKey).concat(items);results=latestSlices(items);renderSlices();}
function leaveHistory(){if(!historySnapshot||busy)return;const saved=historySnapshot;historySnapshot=null;resultMarker.after($('detailResult'));viewingHistory=false;historyGroupKey=null;results=currentResults.slice();referenceImage=saved.referenceImage;renderSlices();setBatch(saved.batch);selected=saved.selected;for(const item of saved.editor){const el=$(item.id);if(item.value!==undefined)el.value=item.value;el.hidden=item.hidden;if(item.text!==null)el.textContent=item.text;if(item.html!==null)el.innerHTML=item.html;el.className=item.className;el.style.cssText=item.style;}$('detailReferencePreview').querySelector('img').src=referenceImage||'';$('detailReferencePreview').querySelector('span').textContent=saved.referenceName;if(!results.some(x=>String(x.number)===$('detailEditScope').value))$('detailEditScope').value=String(results[0]?.number||'all');updateScope();$('detailPreviewViewport').scrollTop=saved.previewTop;syncPreviewProgress();}
$('detailHistory').onclick=()=>{if(!busy)window.openGenerationHistory?.('detail',false);};$('detailTrash').onclick=()=>{if(!busy)window.openGenerationHistory?.('detail',true);};function showDetailCurrent(){if(busy)return;viewingHistory=false;results=currentResults.slice();setBatch(false);renderSlices();window.showCurrentGeneration?.();panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});}$('detailCurrent').onclick=showDetailCurrent;$('detailDownloadAll').onclick=()=>downloadGroup([...results,...replacedSlices()],'商品详情页全部图片.zip',{detail:true});
async function removeDetail(group){if(busy)return toast('请等待详情任务完成');try{const source=detailItems().find(x=>String(x.number)===$('detailEditScope').value);if(!source)return;await request('/api/history/delete',group?{groupId:source.batchId||source.jobId}:{number:source.number});await syncArchive();window.refreshImageHistory?.();toast('已移入回收站，可还原');}catch(e){status(e.message);}}
$('detailDeleteOne').onclick=()=>removeDetail(false);$('detailDeleteGroup').onclick=()=>removeDetail(true);
async function syncArchive(){const res=await fetch('/api/history');if(!res.ok)return;const data=await res.json();detailArchive=data.images.filter(x=>x.detailPage);const valid=new Set(data.images.map(x=>x.number));const key=x=>x.detailGroupId||x.batchId||x.jobId;currentResults=currentGroupKey?latestSlices(data.images.filter(x=>x.detailPage&&key(x)===currentGroupKey)):currentResults.filter(x=>valid.has(x.number));results=viewingHistory?latestSlices(data.images.filter(x=>x.detailPage&&key(x)===historyGroupKey)):currentResults.slice();const count=(data.trash||[]).filter(x=>x.detailPage).length;$('detailTrash').textContent='回收站'+(count?' · '+count:'');renderSlices();}
window.addEventListener('archive-updated',()=>syncArchive());
globalThis.detailPages={addGroup,downloadGroup,openGroup,updateHistory,leaveHistory,historyBusy:()=>viewingHistory&&(busy||referenceLoading),canOpenHistory:()=>!busy&&!referenceLoading,showCurrent:showDetailCurrent};
fetch('/api/history').then(r=>r.ok?r.json():null).then(data=>{if(results.length||busy||viewingHistory)return;detailArchive=(data?.images||[]).filter(x=>x.detailPage);const latest=data?.images?.find(item=>item.detailPage);if(!latest)return;const group=latest.detailGroupId||latest.batchId||latest.jobId;const related=data.images.filter(x=>x.detailPage&&(x.detailGroupId||x.batchId||x.jobId)===group);const byIndex=new Map();for(const item of related.sort((a,b)=>b.number-a.number)){const index=item.detailSliceIndex||0;if(!byIndex.has(index))byIndex.set(index,item);}results=[...byIndex.values()];currentResults=results.slice();currentGroupKey=group;renderSlices();const count=(data.trash||[]).filter(x=>x.detailPage).length;$("detailTrash").textContent="回收站"+(count?" · "+count:"");}).catch(()=>{});
function decorate(){document.querySelectorAll('#thumbnails .add-to-detail,.history-frame .add-to-detail').forEach(button=>button.remove());for(const btn of document.querySelectorAll('.record-picture')){if(btn.dataset.deleted==='true'||btn.querySelector('.add-to-detail'))continue;let item;if(btn.matches('.thumbnail'))item=state.results[Number(btn.dataset.resultIndex)];else{const img=btn.querySelector('img');if(img?.src)item={url:new URL(img.src).pathname,number:Number(btn.dataset.imageNumber)||Number(btn.getAttribute('aria-label')?.match(/#(\d+)/)?.[1])||undefined};}if(!item?.url||item.reference)continue;const add=document.createElement('span');add.className='add-to-detail';add.textContent='加入详情';add.setAttribute('role','button');add.tabIndex=0;add.onclick=e=>{e.stopPropagation();addGroup([item]);};add.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();addGroup([item]);}};btn.append(add);}}
let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{decorate();pending=false;});}).observe(document.body,{childList:true,subtree:true});render();renderSlices();decorate();
